import{_ as a,o as t,c,ag as r}from"./chunks/framework.D1K3FKSn.js";const o="/assets/page2-1.1suXmVac.png",s=JSON.parse('{"title":"Vue 的 computed 和 watch 的区别","description":"","frontmatter":{},"headers":[],"relativePath":"tiku/vue/page2.md","filePath":"tiku/vue/page2.md","lastUpdated":1730965503000}'),h={name:"tiku/vue/page2.md"};function l(i,e,u,d,p,m){return t(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="vue-的-computed-和-watch-的区别" tabindex="-1">Vue 的 computed 和 watch 的区别 <a class="header-anchor" href="#vue-的-computed-和-watch-的区别" aria-label="Permalink to &quot;Vue 的 computed 和 watch 的区别&quot;">​</a></h1><h2 id="相关问题" tabindex="-1">相关问题 <a class="header-anchor" href="#相关问题" aria-label="Permalink to &quot;相关问题&quot;">​</a></h2><ul><li>computed 和 watch 的实现原理</li><li>computed 和 watch 的适用场景</li></ul><h2 id="回答关键点" tabindex="-1">回答关键点 <a class="header-anchor" href="#回答关键点" aria-label="Permalink to &quot;回答关键点&quot;">​</a></h2><p><code>响应变化</code> <code>属性</code> <code>侦听</code></p><p>computed 是模板表达式的声明式描述，会创建新的响应式数据。而 watch 是响应式数据的自定义侦听器，用于响应数据的变化。除此之外，computed 还具有可缓存，可依赖多个属性，getter 函数无副作用等特点。watch 则更适用于异步或开销大的操作。</p><h2 id="知识点深入" tabindex="-1">知识点深入 <a class="header-anchor" href="#知识点深入" aria-label="Permalink to &quot;知识点深入&quot;">​</a></h2><h3 id="_1-实现原理" tabindex="-1">1. 实现原理 <a class="header-anchor" href="#_1-实现原理" aria-label="Permalink to &quot;1. 实现原理&quot;">​</a></h3><p>在了解 Vue 数据双向绑定的基础上，computed 等同于为属性设置 getter 函数（也可设置 setter），而 watch 等同于为属性的 setter 设置回调函数、监听深度 deep 及响应速度 immediate。下面简单讲解下两者的实现原理，具体细节可以参考 <a href="https://github.com/vuejs/vue" target="_blank" rel="noreferrer">源码</a>。</p><h4 id="_1-1-computed-原理" tabindex="-1">1.1 computed 原理 <a class="header-anchor" href="#_1-1-computed-原理" aria-label="Permalink to &quot;1.1 computed 原理&quot;">​</a></h4><p>主要分为四个阶段</p><p><img src="'+o+'" alt="" loading="lazy"></p><ol><li>初始化：为 computed 属性创建 lazy watcher（此处 watcher 指双向绑定中的监听器，下同）。</li><li>首次模板渲染：渲染 watcher 检测到 computed 属性时，会调用 computed 属性的 getter 方法，而 computed 属性的 getter 方法会调用依赖属性的 getter，从而形成链式调用，同时保存引用关系用于更新。取得计算结果后 lazy watcher 会将结果缓存，并返回给渲染 watcher 进行模板渲染。</li><li>多次模板渲染：直接取 lazy watcher 中的缓存值给到渲染 watcher 进行渲染。</li><li>依赖属性更新：根据首次模板渲染阶段构建的依赖关系向上通知 lazy watcher 进行重新计算，缓存计算结果并通知渲染 watcher 重新渲染更新页面。</li></ol><h4 id="_1-2-watch-原理" tabindex="-1">1.2 watch 原理 <a class="header-anchor" href="#_1-2-watch-原理" aria-label="Permalink to &quot;1.2 watch 原理&quot;">​</a></h4><p>watch 本质上是为每个监听属性 setter 创建了一个 watcher，当被监听的属性更新时，调用传入的回调函数。常见的配置选项有 deep 和 immediate，对应原理如下：</p><ol><li>deep：深度监听对象，为对象的每一个属性创建一个 watcher，从而确保对象的每一个属性更新时都会触发传入的回调函数。主要原因在于对象属于引用类型，单个属性的更新并不会触发对象 setter，因此引入 2.deep 能够很好地解决监听对象的问题。同时也会引入判断机制，确保在多个属性更新时回调函数仅触发一次，避免性能浪费。</li><li>immediate：在初始化时直接调用回调函数，可以通过在 created 阶段手动调用回调函数实现相同的效果。</li></ol><h3 id="_2-适用场景" tabindex="-1">2. 适用场景 <a class="header-anchor" href="#_2-适用场景" aria-label="Permalink to &quot;2. 适用场景&quot;">​</a></h3><ul><li>computed：需要处理复杂逻辑的模板表达式。</li><li>watch：需要执行异步或开销较大的操作。</li></ul><p>从表现上看，computed 会创建新的属性，而 watch 可以通过将属性设置在 data 中，再监听依赖属性变化，调用 handler 方法更新属性的方式达到同样的效果。因此不难得出 computed 的使用场景可以被 watch 覆盖这一结论。但在具体的使用上还是优先考虑 computed，因为相同场景下 watch 所需的代码量和性能开销一般来说会比 computed 大。在 computed 无法满足需求的情况下再考虑使用 watch，也可以有效避免 watch 滥用，提升性能。</p><h3 id="_3-vue3-与-vue2-区别" tabindex="-1">3. Vue3 与 Vue2 区别 <a class="header-anchor" href="#_3-vue3-与-vue2-区别" aria-label="Permalink to &quot;3. Vue3 与 Vue2 区别&quot;">​</a></h3><p>Vue3 中 computed 和 watch 的原理以及在 Options API 中的使用方式和 Vue2 保持一致。但在 Vue3 的新特性组合式（Composition）API 中，使用方式和功能相比 Vue2 有了明显差别。使用方式由原来在组件中声明改为直接从 Vue 中导入使用，各自的调用方式和参数也发生了改变，功能更加多样，同时 Vue3 还引入了 watchEffect 作为 watch 的补充，以求用更简洁的代码来覆盖更广的使用场景。具体使用参考<a href="https://cn.vuejs.org/" target="_blank" rel="noreferrer">官方文档</a>。</p>',21)])])}const w=a(h,[["render",l]]);export{s as __pageData,w as default};
